这里应该是：

```cpp
parent[root_right] = root_left;
```

因为 `root_right` 是较小连通块的根，`root_left` 是较大连通块的根。按大小合并要做的是让较小根指向较大根，而不是让它继续指向自己。否则这条边实际上没有完成合并，最终连通分量数量会偏大。

下面是修正后的完整代码留档：

```cpp
#include <vector>
#include <stdexcept>

int uf_find_root(std::vector<int> parent, int x) {
  if (x < 0 || x >= static_cast<int>(parent.size())) {
    throw std::invalid_argument("节点越界");
  }
  while (parent[x] != x) {
    x = parent[x];
  }
  return x;
}

std::vector<int> uf_compress(std::vector<int> parent, int x) {
  if (x < 0 || x >= static_cast<int>(parent.size())) {
    throw std::invalid_argument("节点越界");
  }

  int root = x;
  while (parent[root] != root) {
    root = parent[root];
  }

  std::vector<int> result = parent;
  int cursor = x;
  while (result[cursor] != root) {
    int nxt = result[cursor];
    result[cursor] = root;
    cursor = nxt;
  }

  return result;
}

int count_components(int node_count, std::vector<std::vector<int>> edges) {
  if (node_count <= 0) {
    throw std::invalid_argument("节点数必须是正整数");
  }

  std::vector<int> parent(node_count);
  std::vector<int> sizes(node_count, 1);

  for (int i = 0; i < node_count; ++i) {
    parent[i] = i;
  }

  for (const auto& edge : edges) {
    if (edge.size() != 2) {
      throw std::invalid_argument("每条边必须是长度为 2 的容器");
    }

    int left = edge[0];
    int right = edge[1];

    if (left < 0 || left >= node_count || right < 0 || right >= node_count) {
      throw std::invalid_argument("端点越界");
    }

    if (left == right) {
      throw std::invalid_argument("不允许自环");
    }

    int root_left = left;
    int root_right = right;

    while (parent[root_left] != root_left) {
      root_left = parent[root_left];
    }
    while (parent[root_right] != root_right) {
      root_right = parent[root_right];
    }

    if (root_left == root_right) {
      continue;
    }

    if (sizes[root_left] < sizes[root_right]) {
      int tmp = root_left;
      root_left = root_right;
      root_right = tmp;
    }

    parent[root_right] = root_left;
    sizes[root_left] += sizes[root_right];
  }

  int roots = 0;
  for (int node = 0; node < node_count; ++node) {
    if (parent[node] == node) {
      ++roots;
    }
  }

  return roots;
}
```

关键改动只有一个：

```cpp
parent[root_right] = root_left;
```

这样才真正完成了“较小根挂到较大根”的合并操作。其余部分，包括边界检查、自环检查、按大小合并、最后统计根节点数量，都是正确的。你的整体思路和实现已经没问题了，修正这一行后就可以作为最终版本留档。

